var text = "attack at dawn";
var result = "";
for (var i = 0; i < text.length; i++) {
  var code = text.charCodeAt(i);
  if (code >= 97 && code <= 122) {
    result += String.fromCharCode((code - 97 + 5) % 26 + 97);
  } else {
    result += text.charAt(i);
  }
}
console.log(result);
